public class Test3 {
    public static int calculate() {
        int x = 10;
        try {
            x += 5;
            return x;
        } catch (Exception e) {
            x += 10;
            return x;
        } finally {
            x += 20;
            return x;
        }
    }
    public static void main(String[] args) {
        System.out.println(calculate());
    }
}

